      "뉴뮤지엄의 공백은 현재 전시 중인 것을 표시하는 라벨이다. This is Gallery의 슬롯은 “This is …”라고 말하며 관람객이 바라보는 대상을 가리킨다. 한 사람이 다른 사람에게 무언가를 보여주듯 말하는 어조를 유지하자.",
