  "5-9(1)": [
    [6.41, 5.22, 6.51, 6.79, "굿즈"],
    [
      6.41,
      15.51,
      72.09,
      4.24,
      "이야기의 세계는 굿즈를 통해 계속 이어집니다. 이야기가 열려 있는 동안 굿즈를 판매하며, 마당에서 적립한 포인트를 굿즈 구매에 사용할 수 있습니다.",
    ],
    [
      6.41,
      21.62,
      66.56,
      7.3,
      "포인트는 1,000원 단위로 사용합니다. 각 제품은 자신이 비롯된 이야기와 연결됩니다. 구매 결정 요인 중 이야기가 2위(27%)를 차지하고 있으며, 응답자의 46%는 좋아하는 이야기를 담은 굿즈에 3만~7만 원을 지출할 의향이 있기 때문입니다(4.5).",
    ],
    [
      6.41,
      30.79,
      50.9,
      7.3,
      "굿즈는 두 가지 에디션으로 구성됩니다. 필름 에디션은 스핀오프 영상 속 장면을 일상용품에 담아 이야기를 가까이 간직할 수 있게 합니다. 마스터피스 에디션은 네 동물을 유명한 명화 속에 담아냅니다.",
    ],
  ],
